args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?personLabel ?birth ?death ?years WHERE {
  VALUES ?person { dbr:Guido_Lauri dbr:Joris_Van_Severen }
  OPTIONAL { ?person dbo:birthDate ?birth. }
  OPTIONAL { ?person dbo:deathDate ?death. }
  OPTIONAL { ?person rdfs:label ?personLabel. FILTER(lang(?personLabel) = 'en') }
  BIND(IF(BOUND(?birth) && BOUND(?death), (YEAR(xsd:dateTime(?death)) - YEAR(xsd:dateTime(?birth))), "") AS ?years)
} ORDER BY ?personLabel

